/*
 * Test-only LD_PRELOAD shim that simulates the CVE-2024-32021 TOCTOU:
 * right before the clone code calls link(src, dest) for the first object
 * file, replace the (already lstat'ed, regular) source file with a symlink
 * to an identical copy. On Linux link() does not dereference, so the
 * created destination is a hardlink to the symlink and thus differs from
 * the iter->st the clone observed. The patched clone must abort.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>

static int (*real_link)(const char *, const char *);
static int armed = 1;

static int copy_file(const char *from, const char *to)
{
	char buf[65536];
	int in = open(from, O_RDONLY);
	int out;
	ssize_t n;

	if (in < 0)
		return -1;
	out = open(to, O_WRONLY | O_CREAT | O_TRUNC, 0644);
	if (out < 0) {
		close(in);
		return -1;
	}
	while ((n = read(in, buf, sizeof(buf))) > 0) {
		if (write(out, buf, n) != n)
			break;
	}
	close(in);
	close(out);
	return 0;
}

int link(const char *oldpath, const char *newpath)
{
	const char *copy_path;

	if (!real_link)
		real_link = dlsym(RTLD_NEXT, "link");

	copy_path = getenv("SWAP_SYMLINK_TARGET");
	if (armed && copy_path && strstr(oldpath, "/objects/") && access(oldpath, F_OK) == 0) {
		armed = 0;
		if (copy_file(oldpath, copy_path) == 0) {
			unlink(oldpath);
			if (symlink(copy_path, oldpath) != 0)
				perror("swap: symlink");
			else
				fprintf(stderr, "[shim] swapped '%s' -> symlink to '%s'\n",
					oldpath, copy_path);
		}
	}
	return real_link(oldpath, newpath);
}

